"""Run from the folder containing pyproject.toml:  python fix_evaluate.py
Adds `abuselens evaluate`: per-abuse-type results on the held-out slice + top features."""
from pathlib import Path

root = Path.cwd()
if not (root / "pyproject.toml").exists():
    raise SystemExit("Run this from the folder that contains pyproject.toml")
FILES = [
    ('src/abuselens/models/train.py', '"""Time-based training, calibration, threshold selection and champion/challenger promotion."""\nfrom __future__ import annotations\n\nimport datetime as dt\nimport json\nfrom pathlib import Path\n\nimport joblib\nimport numpy as np\nimport pandas as pd\nimport xgboost as xgb\nfrom sklearn.isotonic import IsotonicRegression\n\nfrom .. import config\nfrom ..features.lexical import ENRICHMENT_FEATURES, FEATURE_NAMES, build_frame\nfrom . import metrics\n\nTARGET_FPR = 0.01\nASSUMED_PREVALENCE = 0.01\n\n\ndef load_dataset(con) -> pd.DataFrame:\n    """Labelled URLs with the timestamp each was first observed (for time-based splits)."""\n    df = con.execute("""\n        SELECT url, 1 AS label, event_ts, host, abuse_type FROM stg_malicious_urls\n        UNION ALL\n        SELECT url, 0 AS label, event_ts, host, \'safe\' AS abuse_type FROM stg_safe_urls\n    """).df()\n    feats = build_frame(df["url"])\n    out = pd.concat([df.reset_index(drop=True), feats], axis=1)\n    # Optional enrichment (NaN when absent; XGBoost handles missing natively).\n    try:\n        enr = con.execute("""\n            SELECT DISTINCT ON (domain) domain AS host, domain_age_days, cert_count\n            FROM raw_enrichment ORDER BY domain, enriched_at DESC""").df()\n    except Exception:\n        enr = pd.DataFrame(columns=["host", *ENRICHMENT_FEATURES])\n    out = out.merge(enr, on="host", how="left")\n    for c in ENRICHMENT_FEATURES:\n        if c not in out:\n            out[c] = np.nan\n    return out\n\n\ndef feature_columns(df: pd.DataFrame) -> list[str]:\n    cols = list(FEATURE_NAMES)\n    # Only use enrichment if it covers a meaningful share of rows.\n    cols += [c for c in ENRICHMENT_FEATURES if c in df and df[c].notna().mean() > 0.3]\n    return cols\n\n\ndef time_split(df: pd.DataFrame, test_frac: float = 0.25, val_frac: float = 0.15, seed: int = 7):\n    """Per-class temporal split: within each label, earlier -> train, next -> calibration, latest -> test.\n\n    Splitting each class by its own timeline matters because safe URLs are sampled in daily\n    snapshots (often a single day early on) while malicious URLs span many days; one global\n    cut would put every safe example on the same side. Ties are broken randomly.\n    """\n    parts = {"tr": [], "va": [], "te": []}\n    for _, g in df.groupby("label"):\n        g = g.sample(frac=1.0, random_state=seed).sort_values("event_ts", kind="stable")\n        i_test = int(len(g) * (1 - test_frac))\n        i_val = int(i_test * (1 - val_frac))\n        parts["tr"].append(g.iloc[:i_val])\n        parts["va"].append(g.iloc[i_val:i_test])\n        parts["te"].append(g.iloc[i_test:])\n    return tuple(pd.concat(parts[k]).reset_index(drop=True) for k in ("tr", "va", "te"))\n\n\ndef fit(train: pd.DataFrame, val: pd.DataFrame, cols: list[str], seed: int = 7) -> dict:\n    pos = max(int(train["label"].sum()), 1)\n    clf = xgb.XGBClassifier(\n        n_estimators=300, max_depth=5, learning_rate=0.08, subsample=0.8, colsample_bytree=0.8,\n        scale_pos_weight=(len(train) - pos) / pos, eval_metric="aucpr",\n        random_state=seed, n_jobs=2, tree_method="hist")\n    clf.fit(train[cols], train["label"])\n    raw_val = clf.predict_proba(val[cols])[:, 1]\n    # scale_pos_weight skews probabilities; isotonic calibration on a later slice fixes that.\n    iso = IsotonicRegression(out_of_bounds="clip", y_min=0, y_max=1).fit(raw_val, val["label"])\n    thr = metrics.threshold_at_fpr(val["label"], iso.predict(raw_val), TARGET_FPR)\n    return {"model": clf, "calibrator": iso, "threshold": thr, "features": cols}\n\n\ndef score(bundle: dict, df: pd.DataFrame) -> np.ndarray:\n    raw = bundle["model"].predict_proba(df[bundle["features"]])[:, 1]\n    return bundle["calibrator"].predict(raw)\n\n\ndef evaluate_bundle(bundle: dict, test: pd.DataFrame) -> dict:\n    s = score(bundle, test)\n    thr_test = metrics.threshold_at_fpr(test["label"], s, TARGET_FPR)\n    m = metrics.evaluate(test["label"], s, bundle["threshold"], ASSUMED_PREVALENCE)\n    # Also report the best-case operating point re-tuned on test (precision@1%FPR).\n    m["at_target_fpr"] = metrics.operating_point(test["label"], s, thr_test, ASSUMED_PREVALENCE)\n    return m\n\n\ndef save(bundle: dict, path: Path, meta: dict) -> None:\n    path.mkdir(parents=True, exist_ok=True)\n    joblib.dump(bundle, path / "bundle.joblib")\n    (path / "meta.json").write_text(json.dumps(meta, indent=2, default=str), encoding="utf-8")\n\n\ndef load(path: Path) -> tuple[dict, dict]:\n    return joblib.load(path / "bundle.joblib"), json.loads((path / "meta.json").read_text(encoding="utf-8"))\n\n\ndef train_and_promote(con, model_dir: Path | None = None) -> dict:\n    model_dir = Path(model_dir or config.MODEL_DIR)\n    df = load_dataset(con)\n    if df["label"].nunique() < 2 or len(df) < 200:\n        raise RuntimeError(f"not enough labelled data to train ({len(df)} rows)")\n    cols = feature_columns(df)\n    train, val, test = time_split(df)\n    challenger = fit(train, val, cols)\n    ch_metrics = evaluate_bundle(challenger, test)\n\n    meta = {\n        "trained_at": dt.datetime.now(dt.timezone.utc).replace(tzinfo=None).isoformat(),\n        "train_range": [str(train.event_ts.min()), str(train.event_ts.max())],\n        "test_range": [str(test.event_ts.min()), str(test.event_ts.max())],\n        "target_fpr": TARGET_FPR, "assumed_prevalence": ASSUMED_PREVALENCE,\n        "n_train": len(train), "metrics": ch_metrics,\n    }\n    champ_dir = model_dir / "champion"\n    decision, champ_metrics = "promoted (no champion)", None\n    if (champ_dir / "bundle.joblib").exists():\n        champ, _ = load(champ_dir)\n        # Same, newest holdout for both models -> apples-to-apples.\n        champ_metrics = evaluate_bundle(champ, test)\n        if ch_metrics["pr_auc"] >= champ_metrics["pr_auc"]:\n            decision = "promoted (challenger >= champion on PR-AUC)"\n        else:\n            decision = "kept champion"\n    meta["decision"], meta["champion_metrics_on_same_holdout"] = decision, champ_metrics\n    save(challenger, model_dir / "challenger", meta)\n    if decision.startswith("promoted"):\n        save(challenger, champ_dir, meta)\n    return meta\n'),
    ('src/abuselens/models/evaluate.py', '"""Honest breakdown of the champion model on its held-out test slice, by abuse type."""\nfrom __future__ import annotations\n\nimport numpy as np\nimport pandas as pd\n\nfrom . import metrics, train\n\n\ndef by_type(bundle: dict, test: pd.DataFrame) -> pd.DataFrame:\n    """Recall per malicious type at the frozen threshold, plus FPR on safe URLs, plus\n    ROC-AUC / PR-AUC of each type against the same safe URLs."""\n    s = train.score(bundle, test)\n    t = test.assign(score=s)\n    safe = t[t.label == 0]\n    rows = [{"slice": "safe (false positives)", "n": len(safe),\n             "flagged_rate": float((safe.score >= bundle["threshold"]).mean()),\n             "roc_auc": np.nan, "pr_auc": np.nan}]\n    for typ, g in t[t.label == 1].groupby("abuse_type"):\n        both = pd.concat([g, safe])\n        m = metrics.evaluate(both.label, both.score, bundle["threshold"], train.ASSUMED_PREVALENCE)\n        rows.append({"slice": typ, "n": len(g), "flagged_rate": float((g.score >= bundle["threshold"]).mean()),\n                     "roc_auc": m["roc_auc"], "pr_auc": m["pr_auc"]})\n    return pd.DataFrame(rows)\n\n\ndef importances(bundle: dict, k: int = 12) -> pd.DataFrame:\n    b = bundle["model"].get_booster()\n    gain = b.get_score(importance_type="total_gain")\n    out = pd.DataFrame({"feature": list(gain), "gain": list(gain.values())})\n    out["share"] = out.gain / out.gain.sum()\n    return out.sort_values("share", ascending=False).head(k).reset_index(drop=True)\n'),
    ('src/abuselens/cli.py', '"""`abuselens` command line: ingest | marts | enrich | train | monitor | report."""\nfrom __future__ import annotations\n\nimport argparse\nimport logging\nimport sys\n\nfrom . import config, db\nfrom .ingest import runner\n\nALL_SOURCES = ["urlhaus", "openphish", "phishtank", "tranco", "commoncrawl", "sitelinks"]\n\n\ndef cmd_ingest(a):\n    con = db.connect()\n    sources = ALL_SOURCES if a.all else a.sources\n    res = runner.run(con, sources)\n    for k, ok in res.items():\n        print(f"{k:10s} {\'ok\' if ok else \'FAILED (see ingest_log)\'}")\n    return 0 if all(res.values()) else 1\n\n\ndef cmd_marts(a):\n    con = db.connect()\n    for sub in ("staging", "marts"):\n        print(sub, db.run_sql_dir(con, sub))\n    return 0\n\n\ndef cmd_enrich(a):\n    from .enrich.context import enrich_domains\n    con = db.connect()\n    hosts = [r[0] for r in con.execute("""\n        SELECT host FROM (SELECT host FROM stg_malicious_urls UNION ALL SELECT host FROM stg_safe_urls)\n        WHERE host NOT SIMILAR TO \'[0-9.]+\' AND host <> \'\'\n          AND host NOT IN (SELECT domain FROM raw_enrichment)\n        GROUP BY host ORDER BY random() LIMIT ?""", [a.max]).fetchall()]\n    df = enrich_domains(hosts, max_n=a.max)\n    con.register("_e", df)\n    con.execute("INSERT INTO raw_enrichment SELECT * FROM _e")\n    print(f"enriched {len(df)} domains")\n    return 0\n\n\ndef cmd_train(a):\n    from .models import train\n    con = db.connect()\n    db.run_sql_dir(con, "staging")\n    meta = train.train_and_promote(con)\n    m = meta["metrics"]\n    print(f"{meta[\'decision\']} | PR-AUC {m[\'pr_auc\']:.3f} ROC-AUC {m[\'roc_auc\']:.3f} "\n          f"recall {m[\'recall\']:.2%} FPR {m[\'fpr\']:.2%}")\n    return 0\n\n\ndef _monitor(con):\n    from .models import train\n    from .monitoring import drift\n    bundle, _ = train.load(config.MODEL_DIR / "champion")\n    return drift.run(con, bundle)\n\n\ndef cmd_evaluate(a):\n    from .models import evaluate, train\n    con = db.connect()\n    db.run_sql_dir(con, "staging")\n    bundle, meta = train.load(config.MODEL_DIR / "champion")\n    _, _, test = train.time_split(train.load_dataset(con))\n    print(f"Held-out test slice: {len(test)} URLs; frozen threshold {bundle[\'threshold\']:.3f}\\n")\n    print(evaluate.by_type(bundle, test).round(4).to_string(index=False))\n    print("\\nTop features by share of total gain:")\n    print(evaluate.importances(bundle).round(4).to_string(index=False))\n    return 0\n\n\ndef cmd_monitor(a):\n    con = db.connect()\n    res = _monitor(con)\n    print(res["decay"].round(3).to_string(index=False))\n    for al in res["alerts"] or ["no alerts"]:\n        print("-", al)\n    return 0\n\n\ndef cmd_report(a):\n    import json\n\n    from .reporting import brief\n    con = db.connect()\n    for sub in ("staging", "marts"):\n        db.run_sql_dir(con, sub)\n    meta_path = config.MODEL_DIR / "champion" / "meta.json"\n    meta = json.loads(meta_path.read_text(encoding="utf-8")) if meta_path.exists() else None\n    try:\n        mon = _monitor(con) if meta else None\n    except Exception:\n        mon = None\n    print(brief.write(brief.build(con, meta, mon)))\n    return 0\n\n\ndef main(argv=None) -> int:\n    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(name)s %(message)s")\n    p = argparse.ArgumentParser(prog="abuselens")\n    sub = p.add_subparsers(dest="cmd", required=True)\n    s = sub.add_parser("ingest")\n    s.add_argument("--all", action="store_true")\n    s.add_argument("--sources", nargs="*", default=[], choices=ALL_SOURCES)\n    s.set_defaults(fn=cmd_ingest)\n    sub.add_parser("marts").set_defaults(fn=cmd_marts)\n    s = sub.add_parser("enrich")\n    s.add_argument("--max", type=int, default=200)\n    s.set_defaults(fn=cmd_enrich)\n    sub.add_parser("train").set_defaults(fn=cmd_train)\n    sub.add_parser("monitor").set_defaults(fn=cmd_monitor)\n    sub.add_parser("evaluate").set_defaults(fn=cmd_evaluate)\n    sub.add_parser("report").set_defaults(fn=cmd_report)\n    a = p.parse_args(argv)\n    return a.fn(a)\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n'),
]
for rel, text in FILES:
    (root / rel).write_text(text, encoding="utf-8", newline="")
    print("patched", rel)
